{"implementation":"def solve(case):
    nodes = list(case["nodes"])
    core_distance = case["core_distance"]
    node_order = {node: index for index, node in enumerate(nodes)}

    edges = []
    for edge_index, item in enumerate(case["distances"]):
        u, v, distance = item
        weight = max(core_distance[u], core_distance[v], distance)
        edges.append((weight, edge_index, u, v))

    edges.sort(key=lambda edge: (edge[0], edge[1]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return False
        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target_count = max(0, len(nodes) - 1)
    for weight, _, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == target_count:
                break

    return {"mst_edges": mst_edges, "total_weight": round(total_weight, 8)}"}
